// FUNCTION: BFME2 0x00140CF0 size=206 name=?Save@SceneClass@@UAEXAAVChunkSaveClass@@@Z evidence=N:ledger
void SceneClass::Save(ChunkSaveClass &csave)
{
	csave.Begin_Chunk(SCENE_CHUNK_VARIABLES);

	csave.Begin_Micro_Chunk(SCENE_MICRO_AMBIENT_LIGHT);
	csave.Write(&AmbientLight, sizeof(AmbientLight));
	csave.End_Micro_Chunk();

	csave.Begin_Micro_Chunk(SCENE_MICRO_POLY_RENDER_MODE);
	csave.Write(&PolyRenderMode, sizeof(PolyRenderMode));
	csave.End_Micro_Chunk();

	csave.Begin_Micro_Chunk(SCENE_MICRO_FOG_COLOR);
	csave.Write(&FogColor, sizeof(FogColor));
	csave.End_Micro_Chunk();

	csave.Begin_Micro_Chunk(SCENE_MICRO_FOG_ENABLED);
	csave.Write(&FogEnabled, sizeof(FogEnabled));
	csave.End_Micro_Chunk();

	csave.Begin_Micro_Chunk(SCENE_MICRO_FOG_START);
	csave.Write(&FogStart, sizeof(FogStart));
	csave.End_Micro_Chunk();

	csave.Begin_Micro_Chunk(SCENE_MICRO_FOG_END);
	csave.Write(&FogEnd, sizeof(FogEnd));
	csave.End_Micro_Chunk();

	csave.End_Chunk();
}

// FUNCTION: BFME2 0x00140DC0 size=144 name=?Load@SceneClass@@UAEXAAVChunkLoadClass@@@Z evidence=N:ledger
void SceneClass::Load(ChunkLoadClass &cload)
{
	cload.Open_Chunk();
	if (cload.Cur_Chunk_ID() == SCENE_CHUNK_VARIABLES) {
		while (cload.Open_Micro_Chunk()) {
			switch (cload.Cur_Micro_Chunk_ID()) {
			case SCENE_MICRO_AMBIENT_LIGHT:
				cload.Read(&AmbientLight, sizeof(AmbientLight));
				break;
			case SCENE_MICRO_POLY_RENDER_MODE:
				cload.Read(&PolyRenderMode, sizeof(PolyRenderMode));
				break;
			case SCENE_MICRO_FOG_COLOR:
				cload.Read(&FogColor, sizeof(FogColor));
				break;
			case SCENE_MICRO_FOG_ENABLED:
				cload.Read(&FogEnabled, sizeof(FogEnabled));
				break;
			case SCENE_MICRO_FOG_START:
				cload.Read(&FogStart, sizeof(FogStart));
				break;
			case SCENE_MICRO_FOG_END:
				cload.Read(&FogEnd, sizeof(FogEnd));
				break;
			}
			cload.Close_Micro_Chunk();
		}
	}
	cload.Close_Chunk();
}

