// FUNCTION: BFME2 0x00141400 size=176 name=?Register@SimpleSceneClass@@UAEXPAVRenderObjClass@@W4RegType@SceneClass@@@Z evidence=N:ledger
void SimpleSceneClass::Register(RenderObjClass *obj, RegType for_what)
{
	switch (for_what) {
	case ON_FRAME_UPDATE:
		UpdateList.Add(obj);
		break;
	case LIGHT:
		LightList.Add_Tail(obj);
		break;
	case RELEASE:
		ReleaseList.Add(obj);
		break;
	case OBJECT_LIST:
		ObjectList.Add(obj);
		break;
	case FORCE_VISIBLE_LIST:
		ForceVisibleList.Add(obj);
		break;
	}
}

// FUNCTION: BFME2 0x001414D0 size=160 name=?Unregister@SimpleSceneClass@@UAEXPAVRenderObjClass@@W4RegType@SceneClass@@@Z evidence=N:ledger
void SimpleSceneClass::Unregister(RenderObjClass *obj, RegType for_what)
{
	switch (for_what) {
	case ON_FRAME_UPDATE:
		UpdateList.Remove(obj);
		break;
	case LIGHT:
		LightList.Remove(obj);
		break;
	case RELEASE:
		ReleaseList.Remove(obj);
		break;
	case OBJECT_LIST:
		ObjectList.Remove(obj);
		break;
	case FORCE_VISIBLE_LIST:
		ForceVisibleList.Remove(obj);
		break;
	}
}

