// FUNCTION: BFME2 0x00141BB0 size=61 name=?Post_Render_Processing@SimpleSceneClass@@MAEXAAVRenderInfoClass@@@Z evidence=N:ledger
void SimpleSceneClass::Post_Render_Processing(RenderInfoClass &rinfo)
{
	// Objects registered for release leave the scene after the frame.
	RefMultiListIterator<RenderObjClass> it(&ReleaseList);
	for (it.First(); !it.Is_Done(); it.Next())
		it.Peek_Obj()->Remove();
	ReleaseList.Reset_List();
}

